const original = $('Telegram Trigger').first().json.message?.text ?? $('Edit Fields').first().json.chatInput ?? '';
const raw = $json.text ?? $json.output ?? $json.response ?? '';
let d;
try {
  d = JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```$/,'').trim());
} catch (e) {
  d = { intent:'UNKNOWN', confidence:0, risk:'HIGH' };
}
const allowed = ['BILLING','TECH_SUPPORT','SALES','UNKNOWN'];
const intent = allowed.includes(d.intent) ? d.intent : 'UNKNOWN';
const confidence = Math.max(0, Math.min(1, Number(d.confidence ?? 0)));
const risk = ['LOW','MEDIUM','HIGH'].includes(d.risk) ? d.risk : 'HIGH';
return [{json:{original_input:original,intent,confidence,risk}}];

// Obtener el resultado devuelto por el Worker o el paso anterior
const item = $json;

// Obtener datos contextuales del Router inicial
const routerData = $('Code in JavaScript').first()?.json ?? {};
const originalInput = routerData.original_input ?? $('Edit Fields').first()?.json.original_input ?? 'Sin dato';

// Fecha formateada en zona horaria local
const now = new Date();
const timestamp = now.toLocaleString('es-AR', { 
  timeZone: 'America/Argentina/Buenos_Aires',
  hour12: false 
});

return [{
  json: {
    timestamp: timestamp,
    original_input: originalInput,
    intent: routerData.intent ?? item.worker ?? 'UNKNOWN',
    confidence: routerData.confidence ?? null,
    risk: routerData.risk ?? 'LOW',
    worker: item.worker ?? 'DESCONOCIDO',
    status: item.status ?? 'success',
    respuesta: item.respuesta ?? (typeof item === 'string' ? item : JSON.stringify(item)),
    requires_human: Boolean(item.requires_human),
    human_decision: item.human_decision ?? (item.requires_human ? 'PENDIENTE' : 'N/A')
  }
}];

// Obtener el contador previo de la memoria (o 0 si es nuevo)
const sesionPrevia = $('Buscar Memoria').first()?.json ?? {};
const contadorPrevio = Number(sesionPrevia.contador_mensajes ?? 0);
const nuevoContador = contadorPrevio + 1;

// Recuperar datos actuales de la ejecución
const item = $json;

return [{
  json: {
    ...item,
    session_id: $('Edit Fields').first().json.chat_id,
    contador_mensajes: nuevoContador,
    debe_resumir: nuevoContador > 5
  }
}];

