// 1. Obtenemos los datos del correo o del input de prueba de forma segura
let input = {};
try {
  input = $('input_de_prueba').first()?.json ?? $('Gmail Trigger').first()?.json ?? {};
} catch (e) {
  input = $('Gmail Trigger').first()?.json ?? {};
}

// 2. Extraemos las filas leídas de la planilla (Logs_Multiagente)
const rows = $input.all().map(i => i.json).filter(r => r && r.session_id);
const m = rows[0] ?? {};

// 3. Devolvemos el contexto limpio listo para el IF y la IA
return [{
  json: {
    ...input,
    memoria_existe: Boolean(m.session_id),
    resumen_consolidado: m.resumen_consolidado ?? 'Sin memoria previa',
    estado_caso: m.estado_caso ?? 'NUEVO',
    datos_clave: m.datos_clave ?? 'Sin datos previos',
    contador_mensajes: Number(m.contador_mensajes ?? 0)
  }
}];

